// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    Rejecter rejecter;

    function setUp() public {
        c = new MyContract();
        rejecter = new Rejecter();
    }

    function testFuzz_property(uint256 amount) public {
        // amount is unbounded: the whole domain is admissible.
        // The test contract is the deployer, hence the owner of c.
        // The reference C requires amount > 0 BEFORE any external transfer, so a
        // zero-amount call by the owner reverts via a bare `require` with EMPTY
        // revert data. The mutant transfers first; a zero-amount low-level
        // `transfer` to the rejecting receiver reverts and bubbles up the
        // receiver's non-empty revert data.
        bytes memory rdata;
        bool ok;
        try c.sendTo(address(rejecter), amount) {
            ok = true;
        } catch (bytes memory d) {
            ok = false;
            rdata = d;
        }
        // General rule: any reverting sendTo call with amount == 0 must carry
        // EMPTY revert data (require-style revert preceding the transfer).
        assertTrue(!(amount == 0 && !ok) || rdata.length == 0, "zero-amount revert must have empty revert data");
    }
}

// Adversarial counterparty: a receiver that always reverts with a custom error,
// so its revert data is non-empty (4-byte selector) and observable when bubbled.
contract Rejecter {
    error DidReject();
    receive() external payable {
        revert DidReject();
    }
}
